function spread(){
  var bp = Math.round((y10 - y2) * 100);
  rk.textContent = '2s10s';
  rv.textContent = (bp >= 0 ? '▲ +' : '▼ −') + Math.abs(bp) + ' bp';
  root.setAttribute('data-dir', bp >= 0 ? 'up' : 'dn');
}
function show(btn){
  dots.forEach(function(d){ d.removeAttribute('data-sel'); });
  tenors.forEach(function(t){ t.removeAttribute('data-sel'); });
  if(!btn){ spread(); return; }
  btn.setAttribute('data-sel','1');
  var i = parseInt(btn.dataset.i, 10);
  if(dots[i]) dots[i].setAttribute('data-sel','1');
  var c = parseFloat(btn.dataset.c);
  rk.textContent = btn.textContent;
  rv.textContent = parseFloat(btn.dataset.y).toFixed(2) + '%  ' + (c >= 0 ? '▲ +' : '▼ −') + Math.abs(Math.round(c*100)) + 'bp';
  root.setAttribute('data-dir', c >= 0 ? 'up' : 'dn');
}
tenors.forEach(function(t){
  t.setAttribute('aria-label', t.textContent + ' yield ' + t.dataset.y + ' percent');
  t.addEventListener('mouseenter', function(){ show(t); });
  t.addEventListener('focus', function(){ show(t); });
  t.addEventListener('click', function(){ show(t); });
  t.addEventListener('mouseleave', function(){ if(document.activeElement !== t) show(null); });
  t.addEventListener('blur', function(){ show(null); });
});
spread();
